import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十卦 解 雷水解 震上坎下","description":"周易 - 第四十卦 解 雷水解 震上坎下","frontmatter":{"title":"第四十卦 解 雷水解 震上坎下","description":"周易 - 第四十卦 解 雷水解 震上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/041.md","filePath":"zh/classics/zhouyi/041.md"}'),l={name:"zh/classics/zhouyi/041.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利西南，无所往，其来复吉。有攸往，夙吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>解，险以动，动而免乎险，解。解利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解，而雷雨作，雷雨作，而百果草木皆甲坼，解之时义大矣哉！</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>雷雨作，解；君子以赦过宥罪。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>无咎。象曰：刚柔之际，义无咎也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>田获三狐，得黄矢，贞吉。象曰：九二贞吉，得中道也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>负且乘，致寇至，贞吝。象曰：负且乘，亦可丑也，自我致戎，又谁咎也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>解而拇，朋至斯孚。象曰：解而拇，未当位也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>君子维有解，吉；有孚于小人。象曰：君子有解，小人退也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>公用射隼，于高墉之上，获之，无不利。象曰：公用射隼，以解悖也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
